  }
  const n=src.length, act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.05-t*0.7))/3
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(sx*0.08-t*1.5)*Math.cos(sy*0.07+t*1.2)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.8))*0.25;
  const cS=0.15, cX=sx*cS, cY=sy*cS, cI=Math.floor(cX), cJ=Math.floor(cY);
