    const ncx=cI+di+Math.sin((cI+di)*1.7+t*0.3)*0.4+Math.cos((cJ+dj)*2.3+t*0.5)*0.3;
    const ncy=cJ+dj+Math.cos((cI+di)*2.1-t*0.4)*0.4+Math.sin((cJ+dj)*1.9-t*0.6)*0.3;
    const d=Math.sqrt((cX-ncx)**2+(cY-ncy)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cellEdge=Math.min(1,(minD2-minD)*8);
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2*0.8-inh2*0.6+spiral*0.5+cellEdge*0.3-0.1)*1.8);
  const combined=r1*0.6+r2*0.4;
  const sx2=sx*0.5,sy2=sy*0.5;
  const micro=Math.tanh((Math.sin(sx2*0.3)*Math.sin(sy2*0.3)+Math.sin((sx2+sy2)*0.2+t*1.5)*0.5)*1.5)*0.2;
  const blend=combined*0.8+micro*0.2, v=blend*0.5+0.5;
  const pal=[
    [5,12,55],[10,40,90],[15,75,115],[18,120,130],
    [45,160,135],[140,185,95],[200,190,60],[220,155,65],
    [215,110,60],[185,70,55],[140,40,50],[90,22,48],
    [45,15,42],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(combined*Math.PI)*0.25;
  const edge=Math.abs(combined)>0.6?1.2:1.0;
  const cellGlow=(1-cellEdge)>0.7?1.1:1.0;
  const m=lum*edge*cellGlow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
